foreach($languages as $i=>$l){$li->execute($l);$courseFind->execute([$l[0]]);$c=$courseFind->fetch();if(!$c){$courseAdd->execute([$l[1].' — Complete Pathway',$l[1],$l[0],$l[2],$l[3],'Beginner','A structured beginner-to-intermediate pathway with 20 guided units.',$l[0]==='en'?1:1]);$courseId=(int)$pdo->lastInsertId();}else{$courseId=(int)$c['id'];}
